add_action( 'add_attachment', 'perfectpixel_product_from_uploaded_image' );

function perfectpixel_product_from_uploaded_image( $attachment_id ) {
	$prefix = '{{upload_product_prefix}}';
	$file   = basename( (string) get_attached_file( $attachment_id ) );
	if ( '' === $prefix || 0 !== strpos( $file, $prefix ) || ! wp_attachment_is_image( $attachment_id ) || ! class_exists( 'WC_Product_Simple' ) ) {
		return;
	}
	$name = trim( preg_replace( '/[-_]+/', ' ', substr( pathinfo( $file, PATHINFO_FILENAME ), strlen( $prefix ) ) ) );

	$product = new WC_Product_Simple();
	$product->set_name( $name ? mb_convert_case( $name, MB_CASE_TITLE, 'UTF-8' ) : 'Νέο προϊόν' );
	$product->set_status( 'draft' );
	$product->set_regular_price( wc_format_decimal( '{{upload_product_price}}' ) );
	$product->set_image_id( $attachment_id );
	$category = (int) '{{upload_product_category_id}}';
	if ( $category ) {
		$product->set_category_ids( array( $category ) );
	}
	$product_id = $product->save();

	if ( $product_id ) {
		wp_update_post( array( 'ID' => $attachment_id, 'post_parent' => $product_id ) );
	}
}
